func (this *Pacifica) ParseMarket(market any) map[string]any {
	//     {
	//       "symbol": "BTC",
	//       "tick_size": "1",
	//       "min_tick": "0",
	//       "max_tick": "1000000",
	//       "lot_size": "0.00001",
	//       "max_leverage": 50,
	//       "isolated_only": false,
	//       "min_order_size": "10",
	//       "max_order_size": "5000000",
	//       "funding_rate": "0.0000125",
	//       "next_funding_rate": "0.0000125",
	//       "created_at": 1748881333944,
	//       "instrument_type": "perpetual",
	//       "base_asset": "BTC"
	//     },
	//     {
	//       "symbol": "SOL-USDC",
	//       "tick_size": "0.01",
	//       "min_tick": "0",
	//       "max_tick": "1000000",
	//       "lot_size": "0.001",
	//       "max_leverage": 1,
	//       "isolated_only": false,
	//       "min_order_size": "10",
	//       "max_order_size": "1000000",
	//       "funding_rate": "0",
	//       "next_funding_rate": "0",
	//       "created_at": 1776615970246,
	//       "instrument_type": "spot",
	//       "base_asset": "SOL"
	//     },
	var id *string = this.SafeString(market, "symbol")
	var baseId *string = this.SafeString(market, "base_asset", id)
	var instrumentType *string = this.SafeString(market, "instrument_type")
	var isSpot bool = (instrumentType != nil && *instrumentType == "spot")
	var isSwap bool = !isSpot
	var quoteId any = "USDC"
	var settleId any = nil
	var typeVar string = "spot"
	var linear any = nil
	var inverse any = nil
	var contractSize *float64 = nil
	var minLeverage any = nil
	var maxLeverage *int64 = nil
	var crossMargin any = nil
	var isolatedMargin any = nil
	if id == nil {
		panic(ExchangeError(this.Id + " parseMarket() missing id"))
	}
	if isSpot {
		var idParts []string = strings.Split(*id, "-")
		quoteId = DerefScalar(this.SafeString(idParts, 1, quoteId))
	}
	var isolatedOnly *bool = this.SafeBool(market, "isolated_only", false)
	if isSwap {
		settleId = quoteId
		typeVar = "swap"
		linear = true
		inverse = false
		contractSize = this.ParseNumber("1")
		minLeverage = 1
		maxLeverage = this.SafeInteger(market, "max_leverage")
		crossMargin = !(isolatedOnly != nil && *isolatedOnly)
		isolatedMargin = true
	}
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	if (base == nil) || (quote == nil) {
		return nil
	}
	var settle *string = this.SafeCurrencyCode(settleId)
	var symbol string = *base + "/" + *quote
	if isSwap {
		symbol = *base + "/" + *quote + ":" + *quote
	}
	var fees map[string]any = SafeMapTyped(this.Fees, typeVar)
	var taker *float64 = this.SafeNumber(fees, "taker")
	var maker *float64 = this.SafeNumber(fees, "maker")
	var amountPrecision *float64 = this.SafeNumber(market, "lot_size")
	var pricePrecision *float64 = this.SafeNumber(market, "tick_size")
	var active bool = true // there is no non-active markets comes from endpoint market info
	return this.SafeMarketStructure(map[string]any{
		"id":             id,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       settleId,
		"type":           typeVar,
		"spot":           isSpot,
		"margin":         false,
		"swap":           isSwap,
		"future":         false,
		"option":         false,
		"active":         active,
		"contract":       isSwap,
		"linear":         linear,
		"inverse":        inverse,
		"taker":          taker,
		"maker":          maker,
		"contractSize":   contractSize,
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": amountPrecision,
			"price":  pricePrecision,
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": minLeverage,
				"max": maxLeverage,
			},
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"price": map[string]any{
				"min": this.SafeNumber(market, "min_tick"),
				"max": this.SafeNumber(market, "max_tick"),
			},
			"cost": map[string]any{
				"min": this.SafeNumber(market, "min_order_size"),
				"max": this.SafeNumber(market, "max_order_size"),
			},
		},
		"created": this.SafeInteger(market, "created_at"),
		"marginModes": map[string]any{
			"cross":    crossMargin,
			"isolated": isolatedMargin,
		},
		"info": market,
	})
}

/**
 * @method
 * @name pacifica#fetchBalance
 * @description query for balance and get the amount of funds available for trading or funds locked in orders
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/account/get-account-info
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.account] will default to walletAddress if not provided
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Pacifica) FetchBalanceAsync(optionalArgs ...any) <-chan AsyncResult[Balances] {
	ch := make(chan AsyncResult[Balances], 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchBalanceBody(ch chan AsyncResult[Balances], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	userAccountparamsOriginAndSingleAddressVariable := this.HandleOriginAndSingleAddress("fetchBalance", params)
	var userAccount *string = SafeStringPtr(userAccountparamsOriginAndSingleAddressVariable[0])
	var paramsOriginAndSingleAddress map[string]any = MapTyped(userAccountparamsOriginAndSingleAddressVariable[1])
	var request map[string]any = map[string]any{
		"account": userAccount,
	}

	r := <-this.PublicGetAccount(this.Extend(request, paramsOriginAndSingleAddress))
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value
	// {
	//   "success": true,
	//   "data": {
	//     "balance": "4970.000323",           // USDC cash (perp collateral)
	//     "fee_level": 0,
	//     "maker_fee": "0.00015",
	//     "taker_fee": "0.0004",
	//     "account_equity": "5478.140323",     // balance + spot_market_value
	//     "cross_account_equity": "5376.512323",
	//     "spot_market_value": "508.14",
	//     "spot_collateral": "406.512",
	//     "available_to_spend": "5376.512323",
	//     "available_to_withdraw": "5376.512323",
	//     "pending_balance": "0",
	//     "pending_interest": "0",
	//     "total_margin_used": "0",
	//     "cross_mmr": "0",
	//     "positions_count": 0,
	//     "orders_count": 0,
	//     "stop_orders_count": 0,
	//     "spot_balances": [
	//       {
	//         "symbol": "SOL",
	//         "amount": "5",
	//         "available_to_withdraw": "5",
	//         "pending_balance": "0",
	//         "daily_withdraw_amount_usd": "0",
	//         "effective_daily_deposit_limit_usd": "50000",
	//         "effective_daily_withdraw_limit_usd": "250000"
	//       }
	//     ],
	//     "updated_at": 1789394568220
	//   },
	//   "error": null,
	//   "code": null
	// }
	var data map[string]any = this.SafeDictMap(response, "data", map[string]any{})
	var result map[string]any = map[string]any{
		"info": data,
	}
	var usdcAccount map[string]any = this.Account()
	usdcAccount["total"] = this.SafeString(data, "balance")
	usdcAccount["used"] = this.SafeString(data, "total_margin_used")
	result["USDC"] = usdcAccount
	var spotBalances []any = SafeListTyped(data, "spot_balances")
	for i := 0; i < len(spotBalances); i++ {
		var balance map[string]any = SafeMapTyped(spotBalances, i)
		var currencyId *string = this.SafeString(balance, "symbol")
		var code *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		account["total"] = this.SafeString(balance, "amount")
		account["free"] = this.SafeString(balance, "available_to_withdraw")
		// skip a spot USDC entry so it can't clobber the perp-collateral account above
		if code != nil {
			if _, ok := result[*code]; !ok {
				result[*code] = account
			}
		}
	}
	var timestamp *int64 = this.SafeInteger(data, "updated_at")
	result["timestamp"] = timestamp
	result["datetime"] = this.Iso8601(timestamp)

	ch <- AsyncResult[Balances]{Value: BalancesFromMap(this.SafeBalance(result).(map[string]any))}
	return nil
}

/**
 * @method
 * @name pacifica#fetchLeverage
 * @description fetch the set leverage for a market
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/account/get-account-settings
 * @param {string} symbol  unified symbol of the market
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.account] will default to walletAddress if not provided
 * @returns {object} a [leverage structure]{@link https://docs.ccxt.com/?id=leverage-structure}
 */
func (this *Pacifica) FetchLeverageAsync(symbol any, optionalArgs ...any) <-chan AsyncResult[Leverage] {
	ch := make(chan AsyncResult[Leverage], 1)
	go this.fetchLeverageBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchLeverageBody(ch chan AsyncResult[Leverage], symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.LoadAccountSettingsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	if this.Markets() == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	userAccountparamsOriginAndSingleAddressVariable := this.HandleOriginAndSingleAddress("fetchLeverage", params)
	userAccount := GetValue(userAccountparamsOriginAndSingleAddressVariable, 0)
	var paramsOriginAndSingleAddress map[string]any = MapTyped(userAccountparamsOriginAndSingleAddressVariable[1])
	var settings any = nil
	if IsEqual(userAccount, this.WalletAddress) {
		settings = this.HandleOption("fetchLeverage", "settings")
	} else {
		var request map[string]any = map[string]any{
			"account": userAccount,
		}

		r2 := <-this.FetchAccountSettingsAsync(this.Extend(request, paramsOriginAndSingleAddress))
		if r2.Err != nil {
			panic(r2.Err)
		}
		if r2.Value == nil {
			settings = nil
		} else {
			settings = r2.Value
		}
	}
	var setting map[string]any = SafeMapTyped(settings, symbol)
	if setting == nil {

		// NOTE: Upon account creation, all markets have margin settings default to cross margin and leverage default to max.
		// When querying this endpoint, all markets with default margin and leverage settings on this account will return blank.
		ch <- AsyncResult[Leverage]{Value: LeverageFromMap(this.ParseLeverageFromMarket(market))}
		return nil
	} else {

		ch <- AsyncResult[Leverage]{Value: LeverageFromMap(this.ParseLeverageFromSetting(symbol, setting))}
		return nil
	}
}
func (this *Pacifica) ParseLeverageFromSetting(symbol any, setting map[string]any) map[string]any {
	// {
	//   "WLFI/USDC:USDC": {
	//       "symbol": "WLFI",
	//       "isolated": false,
	//       "leverage": 5,
	//       "created_at": 1758085929703,
	//       "updated_at": 1758086074002
	//    },
	// }
	var isIsolated *bool = this.SafeBool(setting, "isolated", false)
	var leverage *int64 = this.SafeInteger(setting, "leverage")
	var marginMode string = "cross"
	if isIsolated != nil && *isIsolated {
		marginMode = "isolated"
	}
	return map[string]any{
		"info":          setting,
		"symbol":        symbol,
		"marginMode":    marginMode,
		"longLeverage":  leverage,
		"shortLeverage": leverage,
	}
}
func (this *Pacifica) ParseLeverageFromMarket(market map[string]any) map[string]any {
	var marketLimits map[string]any = SafeMapTyped(market, "limits")
	var leverageLimits map[string]any = SafeMapTyped(marketLimits, "leverage")
	return map[string]any{
		"info":          market,
		"symbol":        this.SafeString(market, "symbol"),
		"marginMode":    this.HandleOption("fetchLeverage", "defaultMarginMode", "cross"),
		"longLeverage":  this.SafeInteger(leverageLimits, "max"),
		"shortLeverage": this.SafeInteger(leverageLimits, "max"),
	}
}

/**
 * @method
 * @name pacifica#fetchAccountSettings
 * @description fetch account's market settings. Settings are cached for walletAddress. To refresh the cache, call loadAccountSettings with refresh=true
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/account/get-account-settings
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.account] will default to walletAddress if not provided
 * @returns {object} Dict repacked from list by symbol key
 */
func (this *Pacifica) FetchAccountSettingsAsync(optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchAccountSettingsBody(ch, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchAccountSettingsBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	userAccountparamsOriginAndSingleAddressVariable := this.HandleOriginAndSingleAddress("fetchAccountSettings", params)
	var userAccount *string = SafeStringPtr(userAccountparamsOriginAndSingleAddressVariable[0])
	var paramsOriginAndSingleAddress map[string]any = MapTyped(userAccountparamsOriginAndSingleAddressVariable[1])
	var request map[string]any = map[string]any{
		"account": userAccount,
	}

	r := <-this.PublicGetAccountSettings(this.Extend(request, paramsOriginAndSingleAddress))
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value

	// {
	//   "success": true,
	//   "data": [
	//     {
	//       "symbol": "WLFI",
	//       "isolated": false,
	//       "leverage": 5,
	//       "created_at": 1758085929703,
	//       "updated_at": 1758086074002
	//     }
	//   ],
	//   "error": null,
	//   "code": null
	// }
	ch <- AsyncResult[map[string]any]{Value: this.ParseAccountSettings(this.SafeList(response, "data", []any{}))}
	return nil
}
func (this *Pacifica) LoadAccountSettingsAsync(optionalArgs ...any) <-chan AsyncResult[bool] {
	ch := make(chan AsyncResult[bool], 1)
	go this.loadAccountSettingsBody(ch, optionalArgs...)
	return ch
}
func (this *Pacifica) loadAccountSettingsBody(ch chan AsyncResult[bool], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var refresh bool = GetArgBool(optionalArgs, 0, false)
	_ = refresh
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var settings any = this.HandleOption("loadAccountSettings", "settings")
	if (IsEqual(settings, nil)) || (refresh == true) {
		this.Options["settings"] = this.CreateSafeDictionary()

		r := <-this.FetchAccountSettingsAsync(params)
		if r.Err != nil {
			panic(r.Err)
		}
		if r.Value == nil {
			settings = nil
		} else {
			settings = r.Value
		}
		this.Options["settings"] = settings
	}
	return nil
}
func (this *Pacifica) ParseAccountSettings(settings any) map[string]any {
	var settingsLen int = GetArrayLength(settings)
	if settingsLen == 0 {
		return map[string]any{}
	}
	var settingsBySymbol map[string]any = map[string]any{}
	for i := 0; i < settingsLen; i++ {
		var setting any = GetValue(settings, i)
		var marketId *string = this.SafeString(setting, "symbol")
		var market map[string]any = this.SafeMarket(marketId)
		var symbol *string = SafeStringPtr(market["symbol"])
		if symbol != nil {
			settingsBySymbol[*symbol] = setting
		}
	}
	return settingsBySymbol
}

/**
 * @method
 * @name pacifica#fetchMarginMode
 * @description fetches the margin mode of the trading pair
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/account/get-account-settings
 * @param {string} symbol unified symbol of the market to fetch the margin mode for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.account] will default to walletAddress if not provided
 * @returns {object} a [margin mode structure]{@link https://docs.ccxt.com/?id=margin-mode-structure}
 */
func (this *Pacifica) FetchMarginModeAsync(symbol any, optionalArgs ...any) <-chan AsyncResult[MarginMode] {
	ch := make(chan AsyncResult[MarginMode], 1)
	go this.fetchMarginModeBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchMarginModeBody(ch chan AsyncResult[MarginMode], symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.LoadAccountSettingsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	userAccountparamsOriginAndSingleAddressVariable := this.HandleOriginAndSingleAddress("fetchMarginMode", params)
	userAccount := GetValue(userAccountparamsOriginAndSingleAddressVariable, 0)
	var paramsOriginAndSingleAddress map[string]any = MapTyped(userAccountparamsOriginAndSingleAddressVariable[1])
	var settings any = nil
	if IsEqual(userAccount, this.WalletAddress) {
		settings = this.HandleOption("fetchMarginMode", "settings")
	} else {
		var request map[string]any = map[string]any{
			"account": userAccount,
		}

		r1 := <-this.FetchAccountSettingsAsync(this.Extend(request, paramsOriginAndSingleAddress))
		if r1.Err != nil {
			panic(r1.Err)
		}
		if r1.Value == nil {
			settings = nil
		} else {
			settings = r1.Value
		}
	}
	// {
	//   "WLFI/USDC:USDC": {
	//       "symbol": "WLFI",
	//       "isolated": false,
	//       "leverage": 5,
	//       "created_at": 1758085929703,
	//       "updated_at": 1758086074002
	//    },
	// }
	var setting map[string]any = SafeMapTyped(settings, symbol)
	if setting == nil {

		// NOTE: Upon account creation, all markets have margin settings default to cross margin and leverage default to max.
		// When querying this endpoint, all markets with default margin and leverage settings on this account will return blank.
		ch <- AsyncResult[MarginMode]{Value: MarginModeFromMap(map[string]any{
			"symbol":     symbol,
			"marginMode": this.HandleOption("fetchMarginMode", "defaultMarginMode", "cross"),
		})}
		return nil
	} else {

		ch <- AsyncResult[MarginMode]{Value: MarginModeFromMap(this.ParseMarginModeFromSetting(symbol, setting))}
		return nil
	}
}
func (this *Pacifica) ParseMarginModeFromSetting(symbol any, setting map[string]any) map[string]any {
	// {
	//       "symbol": "WLFI",
	//       "isolated": false,
	//       "leverage": 5,
	//       "created_at": 1758085929703,
	//       "updated_at": 1758086074002
	//
	// }
	var isIsolated *bool = this.SafeBool(setting, "isolated", false)
	var marginMode string = "cross"
	if isIsolated != nil && *isIsolated {
		marginMode = "isolated"
	}
	return map[string]any{
		"symbol":     symbol,
		"marginMode": marginMode,
		"info":       setting,
	}
}

