func (this *Pacifica) ParseFundingRate(info any, optionalArgs ...any) FundingRate {
	//
	//      {
	//         "funding": "0.00010529",
	//         "mark": "1.084819",
	//         "mid": "1.08615",
	//         "next_funding": "0.00011096",
	//         "open_interest": "3634796",
	//         "oracle": "1.084524",
	//         "symbol": "XPL",
	//         "timestamp": 1759222967974,
	//         "volume_24h": "20896698.0672",
	//         "yesterday_price": "1.3412"
	//       }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(info, "symbol")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var funding *float64 = this.SafeNumber(info, "funding")
	var markPx *float64 = this.SafeNumber(info, "mark")
	var oraclePx *float64 = this.SafeNumber(info, "oracle")
	var nextFundingRate *float64 = this.SafeNumber(info, "next_funding")
	var timestamp *int64 = this.SafeInteger(info, "timestamp")
	var currentHour int64 = this.ParseToInt(((float64(this.Milliseconds()) / 60) / 60) / 1000)
	var fundingTimestamp int64 = (currentHour + 1) * 60 * 60 * 1000
	return FundingRateFromMap(map[string]any{
		"info":                     info,
		"symbol":                   symbol,
		"markPrice":                markPx,
		"indexPrice":               oraclePx,
		"interestRate":             nil,
		"estimatedSettlePrice":     nil,
		"timestamp":                timestamp,
		"datetime":                 this.Iso8601(timestamp),
		"fundingRate":              funding,
		"fundingTimestamp":         fundingTimestamp,
		"fundingDatetime":          this.Iso8601(fundingTimestamp),
		"nextFundingRate":          nextFundingRate,
		"nextFundingTimestamp":     nil,
		"nextFundingDatetime":      nil,
		"previousFundingRate":      nil,
		"previousFundingTimestamp": nil,
		"previousFundingDatetime":  nil,
		"interval":                 "1h",
	})
}

/**
 * @method
 * @name pacifica#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/markets/get-candle-data
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents, support '1m', '3m', '5m', '15m', '30m', '1h', '2h', '4h', '8h', '12h', '1d', '1w', '1M'
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch. 'limit' is priority
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Pacifica) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]OHLCV] {
	ch := make(chan AsyncResult[[]OHLCV], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if since == nil {
		panic(ArgumentsRequired(this.Id + " fetchOHLCV() requires a \"since\" argument"))
	}
	var defaultMaxLimit int = 3950 // 4000 by docs, but in fact >~3960 returns error
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchOHLCV", "paginate", false)
	if paginate {

		r1 := <-this.FetchPaginatedCallDeterministicAsync("fetchOHLCV", symbol, since, limit, timeframe, paramsPaginate, defaultMaxLimit)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes125019 []any = r1.Value
		if retRes125019 == nil {
			ch <- AsyncResult[[]OHLCV]{Value: nil}
		} else {
			ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(retRes125019)}
		}
		return nil
	}
	var tf *string = this.SafeString(this.Timeframes, timeframe, timeframe)
	var request map[string]any = map[string]any{
		"symbol":     market["id"],
		"interval":   tf,
		"start_time": since,
	}
	requestUntil, paramsUntil := this.HandleUntilOption("end_time", request, paramsPaginate)
	var nowMillis int64 = this.Milliseconds()
	var requestedUntil *int64 = this.SafeInteger(requestUntil, "end_time")
	if requestedUntil == nil {
		var durationMillis int64 = this.ParseTimeframe(tf) * 1000
		var candleCount int64 = func() int64 {
			if limit == nil {
				return int64(defaultMaxLimit)
			}
			return *limit
		}()
		if since != nil {
			var windowEnd int64 = this.ParseToInt(this.Sum(*since-1, (candleCount * durationMillis)))
			var until int64 = func() int64 {
				if windowEnd > nowMillis {
					return nowMillis
				}
				return windowEnd
			}()
			requestUntil["end_time"] = until
		}
	}

	r2 := <-this.PublicGetKline(this.Extend(requestUntil, paramsUntil))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	//
	// {
	//   "success": true,
	//   "data": [
	//     {
	//       "t": 1748954160000,
	//       "T": 1748954220000,
	//       "s": "BTC",
	//       "i": "1m",
	//       "o": "105376",
	//       "c": "105376",
	//       "h": "105376",
	//       "l": "105376",
	//       "v": "0.00022",
	//       "n": 2
	//     }
	//   ],
	//   "error": null,
	//   "code": null
	// }
	//
	var candles []any = SafeListTypedDefault(response, "data", []any{})

	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(candles, market, timeframe, since, limit))}
	return nil
}
func (this *Pacifica) ParseOHLCV(ohlcv any, optionalArgs ...any) OHLCV {
	//
	//     {
	//       "t": 1748954160000,
	//       "T": 1748954220000,
	//       "s": "BTC",
	//       "i": "1m",
	//       "o": "105376",
	//       "c": "105376",
	//       "h": "105376",
	//       "l": "105376",
	//       "v": "0.00022",
	//       "n": 2
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	return OHLCVFromList([]any{this.SafeInteger(ohlcv, "t"), this.SafeNumber(ohlcv, "o"), this.SafeNumber(ohlcv, "h"), this.SafeNumber(ohlcv, "l"), this.SafeNumber(ohlcv, "c"), this.SafeNumber(ohlcv, "v")})
}

