/**
 * @method
 * @name pacifica#fetchFundingRateHistory
 * @description fetches historical funding rate prices
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/markets/get-historical-funding
 * @param {string} symbol unified symbol of the market to fetch the funding rate history for
 * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
 * @param {int} [limit] the maximum amount of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.cursor] pagination cursor from prev request (manual use)
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure}
 */
func (this *Pacifica) FetchFundingRateHistoryAsync(optionalArgs ...any) <-chan AsyncResult[[]FundingRateHistory] {
	ch := make(chan AsyncResult[[]FundingRateHistory], 1)
	go this.fetchFundingRateHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchFundingRateHistoryBody(ch chan AsyncResult[[]FundingRateHistory], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " fetchFundingRateHistory() requires a symbol argument"))
	}
	var market map[string]any = this.Market(symbol)
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchFundingRateHistory", "paginate", false)
	var defaultLimit int = 100 // Default max limit
	if paginate {

		r1 := <-this.FetchPaginatedCallCursorAsync("fetchFundingRateHistory", symbol, since, limit, paramsPaginate, "next_cursor", "cursor", nil, defaultLimit)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes211219 []any = r1.Value
		if retRes211219 == nil {
			ch <- AsyncResult[[]FundingRateHistory]{Value: nil}
		} else {
			ch <- AsyncResult[[]FundingRateHistory]{Value: FundingRateHistoriesFromList(retRes211219)}
		}
		return nil
	}
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}
	if limit != nil {
		request["limit"] = limit
	}

	r2 := <-this.PublicGetFundingRateHistory(this.Extend(request, paramsPaginate))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	//
	// {
	//   "success": true,
	//   "data": [
	//     {
	//       "oracle_price": "117170.410304",
	//       "bid_impact_price": "117126",
	//       "ask_impact_price": "117142",
	//       "funding_rate": "0.0000125",
	//       "next_funding_rate": "0.0000125",
	//       "created_at": 1753806934249
	//     },
	//     ...
	//   ],
	//   "next_cursor": "11114Lz77",
	//   "has_more": true
	// }
	//
	var data any = this.AddPaginationCursorToResult(response)
	var result []any = []any{}
	for i := 0; i < GetArrayLength(data); i++ {
		var entry any = GetValue(data, i)
		var timestamp *int64 = this.SafeInteger(entry, "created_at")
		result = append(result, map[string]any{
			"info":        entry,
			"symbol":      market["symbol"],
			"fundingRate": this.SafeNumber(entry, "funding_rate"),
			"timestamp":   timestamp,
			"datetime":    this.Iso8601(timestamp),
		})
	}
	var sorted []any = this.SortBy(result, "timestamp")

	ch <- AsyncResult[[]FundingRateHistory]{Value: FundingRateHistoriesFromList(this.FilterBySinceLimit(sorted, since, limit, "timestamp"))}
	return nil
}

/**
 * @method
 * @name pacifica#fetchTickers
 * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/markets/get-prices
 * @param {string[]} [symbols] unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Pacifica) FetchTickersAsync(optionalArgs ...any) <-chan AsyncResult[map[string]Ticker] {
	ch := make(chan AsyncResult[map[string]Ticker], 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchTickersBody(ch chan AsyncResult[map[string]Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)

	r1 := <-this.PublicGetInfoPrices(params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//  {
	//   "success": true,
	//   "data": [
	//     {
	//       "funding": "0.00010529",
	//       "mark": "1.084819",
	//       "mid": "1.08615",
	//       "next_funding": "0.00011096",
	//       "open_interest": "3634796",
	//       "oracle": "1.084524",
	//       "symbol": "XPL",
	//       "timestamp": 1759222967974,
	//       "volume_24h": "20896698.0672",
	//       "yesterday_price": "1.3412"
	//     }
	//   ],
	//   "error": null,
	//   "code": null
	// }
	//
	var data []any = SafeListTyped(response, "data")
	var result map[string]any = map[string]any{}
	for i := 0; i < len(data); i++ {
		var info any = data[i]
		var ticker map[string]any = TickerToMap(this.ParseTicker(info))
		var symbol *string = this.SafeString(ticker, "symbol")
		if symbol != nil {
			result[*symbol] = ticker
		}
	}

	ch <- AsyncResult[map[string]Ticker]{Value: TickerMapFromMap(this.FilterByArrayTickers(result, "symbol", symbolsNormalized))}
	return nil
}
func (this *Pacifica) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	//     {
	//       "funding": "0.00010529",
	//       "mark": "1.084819",
	//       "mid": "1.08615",
	//       "next_funding": "0.00011096",
	//       "open_interest": "3634796",
	//       "oracle": "1.084524",
	//       "symbol": "XPL",
	//       "timestamp": 1759222967974,
	//       "volume_24h": "20896698.0672",
	//       "yesterday_price": "1.3412"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "symbol")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var timestamp *int64 = this.SafeInteger(ticker, "timestamp")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"previousClose": this.SafeNumber(ticker, "yesterday_price"),
		"close":         this.SafeNumber(ticker, "mid"),
		"bid":           nil,
		"ask":           nil,
		"quoteVolume":   this.SafeNumber(ticker, "volume_24h"),
		"info":          ticker,
	}, marketResolved)
}

