/**
 * @method
 * @name pacifica#fetchOrders
 * @description fetch all orders
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/orders/get-order-history
 * @param {string} symbol unified market symbol
 * @param {int} [since] the earliest time in ms to fetch open orders for
 * @param {int} [limit] the maximum number of open orders structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.account] will default to walletAddress if not provided
 * @param {string} [params.cursor] pagination cursor from prev request (manual use)
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {Order[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Pacifica) FetchOrdersAsync(optionalArgs ...any) <-chan AsyncResult[[]Order] {
	ch := make(chan AsyncResult[[]Order], 1)
	go this.fetchOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchOrdersBody(ch chan AsyncResult[[]Order], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchOrders", "paginate", false)
	var defaultLimit int = 100 // max default 100
	if paginate {

		r1 := <-this.FetchPaginatedCallCursorAsync("fetchOrders", symbol, since, limit, paramsPaginate, "next_cursor", "cursor", nil, defaultLimit)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes237619 []any = r1.Value
		if retRes237619 == nil {
			ch <- AsyncResult[[]Order]{Value: nil}
		} else {
			ch <- AsyncResult[[]Order]{Value: OrdersFromList(retRes237619)}
		}
		return nil
	}
	userAddressparamsOriginAndSingleAddressVariable := this.HandleOriginAndSingleAddress("fetchOrders", paramsPaginate)
	var userAddress *string = SafeStringPtr(userAddressparamsOriginAndSingleAddressVariable[0])
	var paramsOriginAndSingleAddress map[string]any = MapTyped(userAddressparamsOriginAndSingleAddressVariable[1])
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
	}
	var request map[string]any = map[string]any{
		"account": userAddress,
	}
	if limit != nil {
		request["limit"] = limit
	}

	r2 := <-this.PublicGetOrdersHistory(this.Extend(request, paramsOriginAndSingleAddress))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	//
	// {
	//   "success": true,
	//   "data": [
	//     {
	//       "order_id": 315992721,
	//       "client_order_id": "ade",
	//       "symbol": "XPL",
	//       "side": "ask",
	//       "initial_price": "1.0865",
	//       "average_filled_price": "0",
	//       "amount": "984",
	//       "filled_amount": "0",
	//       "order_status": "open",
	//       "order_type": "limit",
	//       "stop_price": null,
	//       "stop_parent_order_id": null,
	//       "reduce_only": false,
	//       "reason": null,
	//       "created_at": 1759224893638,
	//       "updated_at": 1759224893638
	//     },
	//     ...
	//   ],
	//   "next_cursor": "1111Hyd74",
	//   "has_more": true
	// }
	//
	var data any = this.AddPaginationCursorToResult(response)

	ch <- AsyncResult[[]Order]{Value: OrdersFromList(this.ParseOrders(data, market, since, limit))}
	return nil
}
func (this *Pacifica) AddPaginationCursorToResult(response any) any {
	var data any = this.SafeList(response, "data", []any{})
	var paginationCursor *string = this.SafeString(response, "next_cursor")
	var hasMore *bool = this.SafeBool(response, "has_more", false)
	var dataLength int = GetArrayLength(data)
	if hasMore != nil && *hasMore {
		if (paginationCursor != nil) && (dataLength > 0) {
			var first any = GetValue(data, 0)
			AddElementToObject(first, "next_cursor", paginationCursor)
			AddElementToObject(first, "has_more", hasMore)
			AddElementToObject(data, 0, first)
		}
	}
	return data
}

/**
 * @method
 * @name pacifica#fetchOrder
 * @description fetches information on an order made by the user
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/orders/get-order-history-by-id
 * @param {string} id order id
 * @param {string} symbol (optional) unified symbol of the market the order was made in
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} An [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Pacifica) FetchOrderAsync(id string, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.fetchOrderBody(ch, id, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchOrderBody(ch chan AsyncResult[Order], id string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
	}
	var request map[string]any = map[string]any{
		"order_id": id,
	}

	r1 := <-this.PublicGetOrdersHistoryById(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	// {
	//   "success": true,
	//   "data": [
	//     {
	//       "history_id": 641452639,
	//       "order_id": 315992721,
	//       "client_order_id": "ade1aa6...",
	//       "symbol": "XPL",
	//       "side": "ask",
	//       "price": "1.0865",
	//       "initial_amount": "984",
	//       "filled_amount": "0",
	//       "cancelled_amount": "984",
	//       "event_type": "cancel",
	//       "order_type": "limit",
	//       "order_status": "cancelled",
	//       "stop_price": null,
	//       "stop_parent_order_id": null,
	//       "reduce_only": false,
	//       "created_at": 1759224895038
	//     },
	//     {
	//       "history_id": 641452513,
	//       "order_id": 315992721,
	//       "client_order_id": "ade1aa6...",
	//       "symbol": "XPL",
	//       "side": "ask",
	//       "price": "1.0865",
	//       "initial_amount": "984",
	//       "filled_amount": "0",
	//       "cancelled_amount": "0",
	//       "event_type": "make",
	//       "order_type": "limit",
	//       "order_status": "open",
	//       "stop_price": null,
	//       "stop_parent_order_id": null,
	//       "reduce_only": false,
	//       "created_at": 1759224893638
	//     }
	//   ],
	//   "error": null,
	//   "code": null
	// }
	//
	var data []any = SafeListTyped(response, "data")
	// return last state, history_id is the per-event sequence, created_at can tie within a millisecond
	var sorted []any = this.SortBy(data, "history_id", true)
	var lastIdx int = len(sorted)
	var lastInfo any = map[string]any{}
	if lastIdx > 0 {
		lastInfo = DerefScalar(sorted[0])
	}

	ch <- AsyncResult[Order]{Value: this.ParseOrder(lastInfo, market)}
	return nil
}
func (this *Pacifica) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"open":             "open",
		"partially_filled": "open",
		"filled":           "closed",
		"cancelled":        "canceled",
		"rejected":         "failed",
	}
	return this.SafeString(statuses, status, status)
}
