	var statuses map[string]any = map[string]any{
		"stop_limit":         "limit",
		"stop_market":        "market",
		"take_profit_limit":  "limit",
		"stop_loss_limit":    "limit",
		"take_profit_market": "market",
		"stop_loss_market":   "market",
	}
	return this.SafeString(statuses, status, status)
