func (this *Pacifica) ParseOrder(order any, optionalArgs ...any) Order {
	//
	// fetchOpenOrders
	//   [
	//     {
	//       "order_id": 315979358,
	//       "client_order_id": "add9a4b5-c7f7-4124-b57f-86982d86d479",
	//       "symbol": "ASTER",
	//       "side": "ask",
	//       "price": "1.836",
	//       "initial_amount": "85.33",
	//       "filled_amount": "0",
	//       "cancelled_amount": "0",
	//       "stop_price": null,
	//       "order_type": "limit",
	//       "stop_parent_order_id": null,
	//       "reduce_only": false,
	//       "created_at": 1759224706737,
	//       "updated_at": 1759224706737
	//     }
	//   ],
	//
	// fetchOrders
	//  [
	//     {
	//       "order_id": 315992721,
	//       "client_order_id": "ade",
	//       "symbol": "XPL",
	//       "side": "ask",
	//       "initial_price": "1.0865",
	//       "average_filled_price": "0",
	//       "amount": "984",
	//       "filled_amount": "0",
	//       "order_status": "open",
	//       "order_type": "limit",
	//       "stop_price": null,
	//       "stop_parent_order_id": null,
	//       "reduce_only": false,
	//       "reason": null,
	//       "created_at": 1759224893638,
	//       "updated_at": 1759224893638
	//     },
	//  ]
	//
	// fetchOrder
	//     {
	//       "history_id": 641452639,
	//       "order_id": 315992721,
	//       "client_order_id": "ade1aa6...",
	//       "symbol": "XPL",
	//       "side": "ask",
	//       "price": "1.0865",
	//       "initial_amount": "984",
	//       "filled_amount": "0",
	//       "cancelled_amount": "984",
	//       "event_type": "cancel",
	//       "order_type": "limit",
	//       "order_status": "cancelled",
	//       "stop_price": null,
	//       "stop_parent_order_id": null,
	//       "reduce_only": false,
	//       "created_at": 1759224895038
	//     }
	//
	// websocket watchOrders
	//     {
	//       "i": 1559665358,
	//       "I": null,
	//       "u": "BrZp5bidJ3WUvceSq7X78bhjTfZXeezzGvGEV4hAYKTa",
	//       "s": "BTC",
	//       "d": "bid",
	//       "p": "89501",
	//       "ip": "89501",
	//       "lp": "89501",
	//       "a": "0.00012",
	//       "f": "0.00012",
	//       "oe": "fulfill_limit",
	//       "os": "filled",
	//       "ot": "limit",
	//       "sp": null,
	//       "si": null,
	//       "r": false,
	//       "ct": 1765017049008,
	//       "ut": 1765017219639,
	//       "li": 1559696133
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString2(order, "symbol", "s")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var timestamp *int64 = this.SafeInteger2(order, "created_at", "ct")
	var status *string = this.SafeString2(order, "order_status", "os", "open") // open if method is fetchOpenOrders
	var side *string = this.SafeString(order, "side", "d")
	if side != nil {
		side = SafeStringPtr(func() string {
			if side != nil && *side == "bid" {
				return "buy"
			}
			return "sell"
		}())
	}
	var totalAmount *string = this.SafeString2(order, "initial_amount", "a")
	var filledAmount *string = this.SafeString2(order, "filled_amount", "f")
	var remaining *string = Precise.StringSub(totalAmount, filledAmount)
	var average *string = this.SafeString2(order, "average_filled_price", "p")
	var eventType *string = this.SafeString(order, "event_type")
	var isFillEvent bool = this.InArray(eventType, []any{"fulfill_market", "fulfill_limit"})
	if (average == nil) && isFillEvent {
		average = this.SafeString(order, "price") // on a matching event price is the fill price
	}
	return this.SafeOrder(map[string]any{
		"info":                order,
		"id":                  this.SafeString2(order, "order_id", "i"),
		"clientOrderId":       this.SafeString2(order, "client_order_id", "I"),
		"timestamp":           timestamp,
		"datetime":            this.Iso8601(timestamp),
		"lastTradeTimestamp":  nil,
		"lastUpdateTimestamp": this.SafeInteger2(order, "updated_at", "ut"),
		"symbol":              symbol,
		"type":                this.ParseOrderType(this.SafeStringLower2(order, "order_type", "ot")),
		"timeInForce":         nil,
		"postOnly":            nil,
		"reduceOnly":          this.SafeBool2(order, "reduce_only", "r"),
		"side":                side,
		"price":               this.SafeString2(order, "price", "lp"),
		"triggerPrice":        this.SafeNumber2(order, "stop_price", "sp"),
		"amount":              totalAmount,
		"cost":                nil,
		"average":             average,
		"filled":              filledAmount,
		"remaining":           remaining,
		"status":              this.ParseOrderStatus(status),
		"fee":                 nil,
		"trades":              nil,
	}, marketResolved)
}

