func (this *Pacifica) fetchPositionsBody(ch chan AsyncResult[[]Position], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	userAddressparamsOriginAndSingleAddressVariable := this.HandleOriginAndSingleAddress("fetchPositions", params)
	var userAddress *string = SafeStringPtr(userAddressparamsOriginAndSingleAddressVariable[0])
	var paramsOriginAndSingleAddress map[string]any = MapTyped(userAddressparamsOriginAndSingleAddressVariable[1])
	var symbolsNormalized []string = this.MarketSymbols(symbols)
	var request map[string]any = map[string]any{
		"account": userAddress,
	}

	r1 := <-this.PublicGetPositions(this.Extend(request, paramsOriginAndSingleAddress))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	// {
	//   "success": true,
	//   "data": [
	//     {
	//       "symbol": "AAVE",
	//       "side": "ask",
	//       "amount": "223.72",
	//       "entry_price": "279.283134",
	//       "margin": "0", // only shown for isolated margin
	//       "funding": "13.159593",
	//       "isolated": false,
	//       "created_at": 1754928414996,
	//       "updated_at": 1759223365538
	//     }
	//   ],
	//   "error": null,
	//   "code": null,
	//   "last_order_id": 1557431179
	// }
	var data []any = SafeListTyped(response, "data")
	var result []any = []any{}
	for i := 0; i < len(data); i++ {
		result = append(result, PositionToMap(this.ParsePosition(data[i], nil)))
	}

	ch <- AsyncResult[[]Position]{Value: PositionsFromList(this.FilterByArrayPositions(result, "symbol", symbolsNormalized))}
	return nil
}
func (this *Pacifica) ParsePosition(position any, optionalArgs ...any) Position {
	//
	//     {
	//       "symbol": "AAVE",
	//       "side": "ask",
	//       "amount": "223.72",
	//       "entry_price": "279.283134",
	//       "margin": "0", // only shown for isolated margin
	//       "funding": "13.159593",
	//       "isolated": false,
	//       "created_at": 1754928414996,
	//       "updated_at": 1759223365538
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "symbol")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var margin *string = this.SafeString(position, "margin")
	var rawIsolated *bool = this.SafeBool(position, "isolated")
	var isIsolated bool = (margin != nil) && (margin == nil || *margin != "0")
	if rawIsolated != nil {
		isIsolated = (rawIsolated != nil && *rawIsolated == true)
	}
	var marginMode string = func() string {
		if isIsolated {
			return "isolated"
		}
		return "cross"
	}()
	var side *string = this.SafeString(position, "side")
	if side != nil {
		side = SafeStringPtr(func() string {
			if side != nil && *side == "bid" {
				return "long"
			}
			return "short"
		}())
	}
	var createdAt *int64 = this.SafeInteger(position, "created_at")
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      symbol,
		"timestamp":                   createdAt,
		"datetime":                    this.Iso8601(createdAt),
		"isolated":                    isIsolated,
		"hedged":                      nil,
		"side":                        side,
		"contracts":                   this.SafeNumber(position, "amount"),
		"contractSize":                nil,
		"entryPrice":                  this.SafeNumber(position, "entry_price"),
		"markPrice":                   nil,
		"notional":                    nil,
		"leverage":                    nil,
		"collateral":                  this.SafeNumber(position, "margin"),
		"initialMargin":               nil,
		"maintenanceMargin":           nil,
		"initialMarginPercentage":     nil,
		"maintenanceMarginPercentage": nil,
		"unrealizedPnl":               nil,
		"liquidationPrice":            this.SafeNumber(position, "liquidation_price"),
		"marginMode":                  marginMode,
		"percentage":                  nil,
	})
}

