/**
 * @method
 * @name pacifica#fetchTradingFees
 * @description fetch the trading fees for multiple markets, the account fee level applies to every market
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/account/get-account-info
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.account] will default to walletAddress if not provided
 * @returns {object} a dictionary of [fee structures]{@link https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
 */
func (this *Pacifica) FetchTradingFeesAsync(optionalArgs ...any) <-chan AsyncResult[map[string]TradingFeeInterface] {
	ch := make(chan AsyncResult[map[string]TradingFeeInterface], 1)
	go this.fetchTradingFeesBody(ch, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchTradingFeesBody(ch chan AsyncResult[map[string]TradingFeeInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	userAddressparamsOriginAndSingleAddressVariable := this.HandleOriginAndSingleAddress("fetchTradingFees", params)
	var userAddress *string = SafeStringPtr(userAddressparamsOriginAndSingleAddressVariable[0])
	var paramsOriginAndSingleAddress map[string]any = MapTyped(userAddressparamsOriginAndSingleAddressVariable[1])
	var request map[string]any = map[string]any{
		"account": userAddress,
	}

	r1 := <-this.PublicGetAccount(this.Extend(request, paramsOriginAndSingleAddress))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var data map[string]any = this.SafeDictMap(response, "data", map[string]any{})
	var result map[string]any = map[string]any{}
	var symbols []string = this.Symbols
	for i := 0; i < len(symbols); i++ {
		var symbol string = symbols[i]
		result[symbol] = TradingFeeInterfaceToMap(this.ParseTradingFee(data, this.Market(symbol)))
	}

	ch <- AsyncResult[map[string]TradingFeeInterface]{Value: TradingFeeInterfaceMapFromMap(result)}
	return nil
}
func (this *Pacifica) ParseTradingFee(fee map[string]any, optionalArgs ...any) TradingFeeInterface {
	//
	//   {
	//     "balance": "2000.000000",
	//     "fee_level": 0,
	//     "maker_fee": "0.00015",
	//     "taker_fee": "0.0004",
	//     "account_equity": "2150.250000",
	//     "available_to_spend": "1800.750000",
	//     "available_to_withdraw": "1500.850000",
	//     "pending_balance": "0.000000",
	//     "total_margin_used": "349.500000",
	//     "cross_mmr": "420.690000",
	//     "positions_count": 2,
	//     "orders_count": 3,
	//     "stop_orders_count": 1,
	//     "updated_at": 1716200000000,
	//     "use_ltp_for_stop_orders": false
	//   }
	//
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var symbol *string = this.SafeSymbol(nil, market)
	return TradingFeeInterfaceFromMap(map[string]any{
		"info":       fee,
		"symbol":     symbol,
		"maker":      this.SafeNumber(fee, "maker_fee"),
		"taker":      this.SafeNumber(fee, "taker_fee"),
		"percentage": nil,
		"tierBased":  nil,
	})
}

