/**
 * @method
 * @name pacifica#fetchOpenInterest
 * @description retrieves the open interest of a contract trading pair
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/markets/get-prices
 * @param {string} symbol unified CCXT market symbol
 * @param {object} [params] exchange specific parameters
 * @returns {object} an [open interest structure]{@link https://docs.ccxt.com/?id=open-interest-structure}
 */
func (this *Pacifica) FetchOpenInterestAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[OpenInterest] {
	ch := make(chan AsyncResult[OpenInterest], 1)
	go this.fetchOpenInterestBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchOpenInterestBody(ch chan AsyncResult[OpenInterest], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolValue any = this.Symbol(symbol)

	r1 := <-this.FetchOpenInterestsAsync([]any{symbolValue}, params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var ois any = nil
	if !StructAbsent(r1.Value) {
		ois = StructBox(r1.Value, OpenInterestMapToMap)
	}
	var oi map[string]any = SafeMapTyped(ois, symbolValue)
	if oi == nil {
		panic(BadSymbol(Add(this.Id+" fetchOpenInterest() could not find open interest for ", symbolValue)))
	}

	ch <- AsyncResult[OpenInterest]{Value: OpenInterestFromMap(oi)}
	return nil
}
func (this *Pacifica) ParseOpenInterest(interest any, optionalArgs ...any) OpenInterest {
	//
	//     {
	//       "funding": "0.00010529",
	//       "mark": "1.084819",
	//       "mid": "1.08615",
	//       "next_funding": "0.00011096",
	//       "open_interest": "3634796",
	//       "oracle": "1.084524",
	//       "symbol": "XPL",
	//       "timestamp": 1759222967974,
	//       "volume_24h": "20896698.0672",
	//       "yesterday_price": "1.3412"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(interest, "symbol")
	var marketResolved any = func() any {
		if marketId != nil {
			return this.SafeMarket(marketId, market)
		}
		return market
	}()
	var symbol *string = nil
	if marketId != nil {
		symbol = this.SafeString(marketResolved, "symbol")
	}
	var interestValue *string = nil
	var markPrice *string = this.SafeString(interest, "mark")
	var openInterest *string = this.SafeString(interest, "open_interest")
	if (openInterest != nil) && (markPrice != nil) {
		interestValue = Precise.StringMul(openInterest, markPrice)
	}
	var timestamp *int64 = this.SafeInteger(interest, "timestamp")
	return this.SafeOpenInterest(map[string]any{
		"symbol":             this.SafeSymbol(symbol),
		"openInterestAmount": this.ParseNumber(openInterest),
		"openInterestValue":  this.ParseNumber(interestValue),
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"info":               interest,
	}, marketResolved)
}

/**
 * @method
 * @name pacifica#fetchLedger
 * @description fetch the history of changes, actions done by the user or operations that altered the balance of the user
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/account/get-account-balance-history
 * @param {string} [code] unified currency code
 * @param {int} [since] timestamp in ms of the earliest ledger entry
 * @param {int} [limit] max number of ledger entries to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.account] will default to walletAddress if not provided
 * @param {string} [params.cursor] pagination cursor from prev request (manual use)
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {object} a [ledger structure]{@link https://docs.ccxt.com/?id=ledger-entry-structure}
 */
func (this *Pacifica) FetchLedgerAsync(optionalArgs ...any) <-chan AsyncResult[[]LedgerEntry] {
	ch := make(chan AsyncResult[[]LedgerEntry], 1)
	go this.fetchLedgerBody(ch, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchLedgerBody(ch chan AsyncResult[[]LedgerEntry], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchLedger", "paginate", false)
	userAddressparamsOriginAndSingleAddressVariable := this.HandleOriginAndSingleAddress("fetchLedger", paramsPaginate)
	var userAddress *string = SafeStringPtr(userAddressparamsOriginAndSingleAddressVariable[0])
	var paramsOriginAndSingleAddress map[string]any = MapTyped(userAddressparamsOriginAndSingleAddressVariable[1])
	var defaultLimit int = 100 // Default max limit
	if paginate {

		r1 := <-this.FetchPaginatedCallCursorAsync("fetchLedger", code, since, limit, paramsOriginAndSingleAddress, "next_cursor", "cursor", nil, defaultLimit)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes311419 []any = r1.Value
		if retRes311419 == nil {
			ch <- AsyncResult[[]LedgerEntry]{Value: nil}
		} else {
			ch <- AsyncResult[[]LedgerEntry]{Value: LedgerEntriesFromList(retRes311419)}
		}
		return nil
	}
	var request map[string]any = map[string]any{
		"account": userAddress,
	}
	if limit != nil {
		request["limit"] = limit
	}

	r2 := <-this.PublicGetAccountBalanceHistory(this.Extend(request, paramsOriginAndSingleAddress))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	// {
	//   "success": true,
	//   "data": [
	//     {
	//       "amount": "100.000000",
	//       "balance": "1200.000000",
	//       "pending_balance": "0.000000",
	//       "event_type": "deposit",
	//       "created_at": 1716200000000
	//     }
	//     ...
	//   ],
	//   "next_cursor": "11114Lz77",
	//   "has_more": true
	// }
	var data any = this.AddPaginationCursorToResult(response)

	ch <- AsyncResult[[]LedgerEntry]{Value: LedgerEntriesFromList(this.ParseLedger(data, nil, since, limit))}
	return nil
}
func (this *Pacifica) ParseLedgerEntry(item any, optionalArgs ...any) LedgerEntry {
	//
	//     {
	//       "amount": "100.000000",
	//       "balance": "1200.000000",
	//       "pending_balance": "0.000000",
	//       "event_type": "deposit",
	//       "created_at": 1716200000000
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var timestamp *int64 = this.SafeInteger(item, "created_at")
	var typeVar *string = this.SafeString(item, "event_type")
	var change *string = this.SafeString(item, "amount")
	var balance *string = this.SafeString(item, "balance")
	var currencyResolved map[string]any = this.SafeCurrency("USDC", currency)
	var direction string
	var amount *string = change
	if Precise.StringLt(amount, "0") {
		direction = "out"
		amount = Precise.StringAbs(amount)
	} else {
		direction = "in"
	}
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               nil,
		"direction":        direction,
		"account":          nil,
		"referenceAccount": nil,
		"referenceId":      nil,
		"type":             this.ParseLedgerEntryType(typeVar),
		"currency":         currencyResolved["code"],
		"amount":           this.ParseNumber(amount),
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"before":           this.ParseNumber(Precise.StringSub(balance, change)),
		"after":            this.ParseNumber(balance),
		"status":           nil,
		"fee":              nil,
	}, currencyResolved)
}
func (this *Pacifica) ParseLedgerEntryType(typeVar *string) *string {
	var ledgerType map[string]any = map[string]any{
		"subaccount_transfer":  "transfer",
		"deposit":              "transaction",
		"deposit_release":      "transaction",
		"withdraw":             "transaction",
		"trade":                "trade",
		"market_liquidation":   "trade",
		"backstop_liquidation": "trade",
		"adl_liquidation":      "trade",
		"funding":              "funding",
		"fee":                  "fee",
		"rebate":               "rebate",
		"cashback":             "cashback",
		"referral":             "referral",
		"airdrop":              "airdrop",
		"payout":               "payout",
	}
	return this.SafeString(ledgerType, typeVar, typeVar)
}

