/**
 * @method
 * @name pacifica#fetchFundingHistory
 * @description fetch the history of funding payments paid and received on this account
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/account/get-funding-history
 * @param {string} [symbol] unified market symbol
 * @param {int} [since] the earliest time in ms to fetch funding history for
 * @param {int} [limit] the maximum number of funding history structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.account] will default to walletAddress if not provided
 * @param {string} [params.cursor] pagination cursor from prev request
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {object} a [funding history structure]{@link https://docs.ccxt.com/?id=funding-history-structure}
 */
func (this *Pacifica) FetchFundingHistoryAsync(optionalArgs ...any) <-chan AsyncResult[[]FundingHistory] {
	ch := make(chan AsyncResult[[]FundingHistory], 1)
	go this.fetchFundingHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Pacifica) fetchFundingHistoryBody(ch chan AsyncResult[[]FundingHistory], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
	}
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchFundingHistory", "paginate", false)
	userAddressparamsOriginAndSingleAddressVariable := this.HandleOriginAndSingleAddress("fetchFundingHistory", paramsPaginate)
	var userAddress *string = SafeStringPtr(userAddressparamsOriginAndSingleAddressVariable[0])
	var paramsOriginAndSingleAddress map[string]any = MapTyped(userAddressparamsOriginAndSingleAddressVariable[1])
	var request map[string]any = map[string]any{
		"account": userAddress,
	}
	if limit != nil {
		request["limit"] = limit
	}
	var defaultLimit int = 100
	if paginate {

		r1 := <-this.FetchPaginatedCallCursorAsync("fetchFundingHistory", symbol, since, limit, paramsOriginAndSingleAddress, "next_cursor", "cursor", nil, defaultLimit)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes333219 []any = r1.Value
		if retRes333219 == nil {
			ch <- AsyncResult[[]FundingHistory]{Value: nil}
		} else {
			ch <- AsyncResult[[]FundingHistory]{Value: FundingHistoriesFromList(retRes333219)}
		}
		return nil
	}

	r2 := <-this.PublicGetFundingHistory(this.Extend(request, paramsOriginAndSingleAddress))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	// {
	//   "success": true,
	//   "data": [
	//     {
	//       "history_id": 2287920,
	//       "symbol": "PUMP",
	//       "side": "ask",
	//       "amount": "39033804",
	//       "payout": "2.617479",
	//       "rate": "0.0000125",
	//       "created_at": 1759222804122
	//     },
	//     ...
	//   ],
	//   "next_cursor": "11114Lz77",
	//   "has_more": true
	// }
	var data any = this.AddPaginationCursorToResult(response)

	ch <- AsyncResult[[]FundingHistory]{Value: FundingHistoriesFromList(this.ParseIncomes(data, market, since, limit))}
	return nil
}
func (this *Pacifica) ParseIncome(income any, optionalArgs ...any) any {
	//
	//     {
	//       "history_id": 2287920,
	//       "symbol": "PUMP",
	//       "side": "ask",
	//       "amount": "39033804",
	//       "payout": "2.617479",
	//       "rate": "0.0000125",
	//       "created_at": 1759222804122
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(income, "history_id")
	var timestamp *int64 = this.SafeInteger(income, "created_at")
	var marketId *string = this.SafeString(income, "symbol")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var amount *string = this.SafeString(income, "payout")
	var code *string = this.SafeCurrencyCode("USDC")
	var rate *float64 = this.SafeNumber(income, "rate")
	return map[string]any{
		"info":      income,
		"symbol":    symbol,
		"code":      code,
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
		"id":        id,
		"amount":    this.ParseNumber(amount),
		"rate":      rate,
	}
}

