func (this *Pacifica) transferBody(ch chan AsyncResult[TransferEntry], code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	var operationType string = "transfer_funds"
	var sigPayload map[string]any = map[string]any{
		"to_account": toAccount,
		"amount":     this.NumberToString(amount),
	}
	var request map[string]any = this.PostActionRequest(operationType, sigPayload, params)
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"expiryWindow"})

	r1 := <-this.PrivatePostAccountSubaccountTransfer(this.Extend(request, paramsOmitted))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	// {
	//   "success": true,
	//   "data": {
	//     "success": true,
	//     "error": null
	//   },
	//   "error": null,
	//   "code": null
	// }
	//
	var data map[string]any = this.SafeDictMap(response, "data", map[string]any{})

	ch <- AsyncResult[TransferEntry]{Value: TransferEntryFromMap(this.Extend(TransferEntryToMap(this.ParseTransfer(data, currency)), map[string]any{
		"amount":      amount,
		"fromAccount": this.SafeString(request, "account"),
		"toAccount":   toAccount,
	}))}
	return nil
}
func (this *Pacifica) ParseTransfer(transfer any, optionalArgs ...any) TransferEntry {
	//
	// {
	//   "success": true,
	//   "data": {
	//     "success": true,
	//     "error": null
	//   },
	//   "error": null,
	//   "code": null
	// }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var success *bool = this.SafeBool(transfer, "success")
	var status *string = nil
	if success != nil {
		status = SafeStringPtr(func() string {
			if success != nil && *success {
				return "ok"
			}
			return "failed"
		}())
	}
	return TransferEntryFromMap(map[string]any{
		"info":        transfer,
		"id":          nil,
		"timestamp":   nil,
		"datetime":    nil,
		"currency":    this.SafeCurrencyCode(nil, currency),
		"amount":      nil,
		"fromAccount": nil,
		"toAccount":   nil,
		"status":      status,
	})
}

/**
 * @method
 * @name pacifica#createSubAccount
 * @description creates a sub-account under the main account, privateKey must be the main account key, the exchange rejects agent-signed requests (an agent_wallet header with a main-key signature is accepted)
 * @see https://docs.pacifica.fi/api-documentation/api/rest-api/subaccounts/create-subaccount
 * @param {string} name unused argument
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.expiryWindow] time to live in milliseconds
 * @param {string} [params.subAccountAddress] - The public key (address) of the sub-account to use for creation
 * @param {string} [params.subAccountPrivateKey] - The private key of the sub-account to use for creation
 * @returns {object} a response object
 */
func (this *Pacifica) CreateSubAccountAsync(name string, optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.createSubAccountBody(ch, name, optionalArgs...)
	return ch
}
func (this *Pacifica) createSubAccountBody(ch chan AsyncResult[map[string]any], name string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var finalHeaders map[string]any = map[string]any{}
	agentAddress, paramsAgentAddress := this.HandleOptionStringAndParams(params, "createSubAccount", "agentAddress")
	originAddressparamsOriginAndSingleAddressVariable := this.HandleOriginAndSingleAddress("createSubAccount", paramsAgentAddress)
	var originAddress *string = SafeStringPtr(originAddressparamsOriginAndSingleAddressVariable[0])
	var paramsOriginAndSingleAddress map[string]any = MapTyped(originAddressparamsOriginAndSingleAddressVariable[1])
	if originAddress == nil {
		panic(ArgumentsRequired(this.Id + " createSubAccount() requires \"originAddress\" in params or \"walletAddress\" in requiredCredentials"))
	}
	if agentAddress != nil {
		finalHeaders["agent_wallet"] = agentAddress
	}
	subAccountAddress, paramsSubAccountAddress := this.HandleOptionStringAndParams(paramsOriginAndSingleAddress, "createSubAccount", "subAccountAddress")
	subAccountPrivateKey, paramsSubAccountPrivateKey := this.HandleOptionStringAndParams(paramsSubAccountAddress, "createSubAccount", "subAccountPrivateKey")
	if subAccountAddress == nil {
		panic(ArgumentsRequired(this.Id + " createSubAccount() requires a \"subAccountAddress\"!"))
	}
	if subAccountPrivateKey == nil {
		panic(ArgumentsRequired(this.Id + " createSubAccount() requires a \"subAccountPrivateKey\"!"))
	}
	var timestampPtr *int64 = nil
	timestampPtr, paramsTimestamp := this.HandleParamInteger(paramsSubAccountPrivateKey, "timestamp", this.Milliseconds())
	timestamp := func() any {
		if timestampPtr != nil {
			return *timestampPtr
		}
		return nil
	}()
	expiryWindow, paramsExpiryWindow := this.HandleOptionIntegerAndParams2(paramsTimestamp, "createSubAccount", "expiryWindow", "expiry_window", 5000)
	var subaccountSignatureHeader map[string]any = map[string]any{
		"timestamp":     timestamp,
		"expiry_window": expiryWindow,
		"type":          "subaccount_initiate",
	}
	var subSigPayload map[string]any = map[string]any{
		"account": originAddress,
	}
	var subaccountSignature string = this.SignMessage(subaccountSignatureHeader, subSigPayload, subAccountPrivateKey)
	var mainSignatureHeader map[string]any = map[string]any{
		"timestamp":     timestamp,
		"expiry_window": expiryWindow,
		"type":          "subaccount_confirm",
	}
	var mainSigPayload map[string]any = map[string]any{
		"signature": subaccountSignature,
	}
	var main_signature string = this.SignMessage(mainSignatureHeader, mainSigPayload, this.PrivateKey)
	finalHeaders["main_account"] = originAddress
	finalHeaders["subaccount"] = subAccountAddress
	finalHeaders["sub_signature"] = subaccountSignature
	finalHeaders["main_signature"] = main_signature
	finalHeaders["timestamp"] = timestamp
	finalHeaders["expiry_window"] = expiryWindow
	var request map[string]any = finalHeaders

	r := <-this.PrivatePostAccountSubaccountCreate(this.Extend(request, paramsExpiryWindow))
	if r.Err != nil {
		panic(r.Err)
	}
	response := r.Value

	//
	// {
	//   "success": true,
	//   "data": null,
	//   "error": null,
	//   "code": null,
	// }
	//
	ch <- AsyncResult[map[string]any]{Value: response}
	return nil
}

