func (this *Pacifica) HandleOriginAndSingleAddress(methodName string, params any) []any {
	address, paramsAccount := this.HandleParamString2(params, "account", "address", nil) // this is for get endpoints that accept account or address
	if address != nil {
		return []any{address, paramsAccount}
	}
	var address1 any = this.WalletAddress
	if address1 != nil {
		return []any{address1, paramsAccount}
	}
	panic(ArgumentsRequired(this.Id + " " + methodName + "() requires address either as \"exchange.walletAddress = ...\" or as parameter or \"address\" in params"))
}
func (this *Pacifica) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil // fallback to default error handler
	}
	//
	//     {"success":false,"data":null,"error":"Beta access required. Signer must redeem a valid beta code.","code":403}
	//     {"success":false,"data":null,"error":"Agent not authorized for account","code":400}
	//     {"success":false,"data":null,"error":"Internal server error","code":500}
	//     {"success":false,"data":null,"error":"Verification failed: signature does not match signer and canonical payload.","code":400,"error_id":"signature_verification_failed"}
	//     {"success":false,"data":null,"error":"Order amount too low for <account>: 7.81140 < 10","code":0,"error_id":"invalid_amount"}
	//     {"success":false,"data":null,"error":"Invalid transfer relationship: <from> -> <to>","code":33,"error_id":"unspecified"}
	//
	// code carries a business code on 422 responses and an echo of the http status otherwise, it is undefined or 200 when all ok
	// the string form is required for the exceptions lookup, an integer key never matches the string-keyed map on the python, go and c# ports
	var errorCode *string = this.SafeString(response, "code")
	var errorId *string = this.SafeString(response, "error_id") // undocumented, present on live errors and more specific than code
	var message *string = this.SafeString(response, "error")
	var error bool
	if (errorCode == nil) || (errorCode != nil && *errorCode == "200") {
		error = false
	} else {
		error = true
	}
	var nonEmptyMessage bool = ((message != nil) && (message == nil || *message != ""))
	if (error == true) || nonEmptyMessage {
		var feedback string = this.Id + " " + body
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorId, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback) // documented message prefixes are more specific than the http-status echo
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
		var statusCode int64 = this.ParseToInt(code)
		var codeAsString string = strconv.FormatInt(code, 10)
		if _, ok := this.HttpExceptions[codeAsString]; (statusCode < 400) || !ok {
			panic(ExchangeError(feedback))
		}
	}
	return nil
}
func (this *Pacifica) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var requestBody *string = nil
	var isTestnet bool = this.IsSandboxModeEnabled
	var urlKey string = "api"
	if isTestnet {
		urlKey = "test"
	}
	var apiName string = api[0]
	var baseApiUrl *string = this.SafeString(this.Urls[urlKey], apiName)
	if baseApiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var host string = this.ImplodeHostname(baseApiUrl)
	var url string = host + "/api/" + this.Version + "/" + this.ImplodeParams(path, params)
	var paramsOmitted any = this.Omit(params, this.ExtractParams(path))
	var headersValue map[string]any = map[string]any{
		"Content-Type": "application/json",
	}
	if paramsOmittedMap, _ := paramsOmitted.(map[string]any); (method == "GET") && (len(paramsOmittedMap) > 0) {
		url += "?" + this.Urlencode(paramsOmitted)
		headersValue["Accept"] = "*/*"
	}
	if method == "POST" {
		jsonText := this.Json(paramsOmitted)
		requestBody = &jsonText
	}
	if !IsEqual(this.HandleOption("sign", "apiKey"), nil) {
		headersValue["PF-API-KEY"] = this.Options["apiKey"]
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    requestBody,
		"headers": headersValue,
	}
}
func (this *Pacifica) CalculateRateLimiterCost(api any, method string, path string, params any, optionalArgs ...any) any {
	var config map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = config
	var cost *string = this.SafeString(config, "cost", "1")
	var costNumber *float64 = this.ParseNumber(cost)
	// 1 is normal POST/GET, 0.5 is cancels, 3-12 is heavy GET
	if costNumber != nil && *costNumber > 1 {
		if !IsEqual(this.HandleOption(method, "apiKey"), nil) {
			var costWithKey any = this.HandleOption(method, "maxCostHugeWithApiKey", 3)
			return costWithKey
		}
	}
	return costNumber
}
func (this *Pacifica) SortJsonKeys(value any) any {
	if this.IsDictionary(value) {
		var result map[string]any = map[string]any{}
		var keys []string = ObjectKeys(value)
		var sortedKeys []any = this.Sort(keys)
		for i := 0; i < len(sortedKeys); i++ {
			var key *string = this.SafeString(sortedKeys, i, "")
			AddElementToObject(result, key, this.SortJsonKeys(GetValue(value, key)))
		}
		return result
	} else if IsArray(value) {
		var sortedList []any = []any{}
		for i := 0; i < GetArrayLength(value); i++ {
			sortedList = append(sortedList, this.SortJsonKeys(GetValue(value, i)))
		}
		return sortedList
	} else {
		return value
	}
}
func (this *Pacifica) PrepareMessage(header map[string]any, payload map[string]any) string {
	var headerType *string = this.SafeString(header, "type")
	var headerTimestamp *int64 = this.SafeInteger(header, "timestamp")
	var headerExpiryWindow *int64 = this.SafeInteger(header, "expiry_window")
	if (headerType == nil) || (headerTimestamp == nil) || (headerExpiryWindow == nil) {
		panic(ArgumentsRequired(this.Id + " prepareMessage() requires type, timestamp, expiry_window in header"))
	}
	var data map[string]any = this.Extend(header, map[string]any{
		"data": payload,
	})
	var sorted any = this.SortJsonKeys(data)
	return this.Json(sorted)
}
func (this *Pacifica) SignMessage(header map[string]any, payload map[string]any, privateKey any) string {
	var message string = this.PrepareMessage(header, payload)
	var messageBytes string = this.Encode(message)
	var secretBytes []byte = this.Base58ToBinary(privateKey)
	var seed []any = this.ArraySlice(secretBytes, 0, 32)
	var signatureBase64 string = Eddsa(messageBytes, seed, ed25519)
	var signatureBinary []byte = this.Base64ToBinary(signatureBase64)
	var signatureBase58 string = this.BinaryToBase58(signatureBinary)
	return signatureBase58
}
func (this *Pacifica) PostActionRequest(operationType string, sigPayload map[string]any, params any) map[string]any {
	this.CheckRequiredCredentials() // check credentials every post action
	if operationType == "undefined" {
		panic(ArgumentsRequired(this.Id + " action: " + operationType + " postActionRequest() requires \"operationType\""))
	}
	if !this.IsSandboxModeEnabled {
		var useBuilder any = this.HandleOption("postActionRequest", "builderFee", true)
		var builderCode any = nil
		if useBuilder == true {
			builderCode = this.HandleOption("postActionRequest", "builderCode")
		}
		if builderCode != nil {
			var isOperationSupportBuilder *bool = this.SafeBool(this.Options["builderSupportOperations"], operationType, false)
			if isOperationSupportBuilder != nil && *isOperationSupportBuilder {
				sigPayload["builder_code"] = builderCode
			}
		}
	}
	expiryWindow, paramsExpiryWindow := this.HandleOptionIntegerAndParams2(params, "postActionRequest", "expiryWindow", "expiry_window", 5000)
	var timestamp *int64 = this.SafeInteger(paramsExpiryWindow, "timestamp", this.Milliseconds())
	var signatureHeader map[string]any = map[string]any{
		"timestamp":     timestamp,
		"expiry_window": expiryWindow,
		"type":          operationType,
	}
	var signature string = this.SignMessage(signatureHeader, sigPayload, this.PrivateKey)
	var finalHeaders map[string]any = map[string]any{}
	agentAddress, paramsAgentAddress := this.HandleOptionStringAndParams(paramsExpiryWindow, "postActionRequest", "agentAddress")
	var originAddress *string = SafeStringPtr(GetValue(this.HandleOriginAndSingleAddress("postActionRequest", paramsAgentAddress), 0))
	if originAddress == nil {
		panic(ArgumentsRequired(this.Id + " action: " + operationType + " postActionRequest() requires \"originAddress\" in params or \"walletAddress\" in requiredCredentials"))
	}
	finalHeaders["account"] = originAddress
	if agentAddress != nil {
		finalHeaders["agent_wallet"] = agentAddress
	}
	finalHeaders["signature"] = signature
	finalHeaders["timestamp"] = this.SafeInteger(signatureHeader, "timestamp")
	finalHeaders["expiry_window"] = this.SafeInteger(signatureHeader, "expiry_window")
	var request map[string]any = this.Extend(finalHeaders, sigPayload)
	return request
}

func NewPacifica(userConfig map[string]any) *Pacifica {
	p := newPacifica()
	p.Init(userConfig)
	return p
}

func (this *Pacifica) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

